Lemma shadow_ext (M M' : word -> option byte) lo hi : (forall x : word, lo <= bv_unsigned x < hi -> M' x = M x) ->
  (forall x : word, lo <= bv_unsigned x < hi -> M x = Some (Z_to_bv 8 0)) -> forall x : word, lo <= bv_unsigned x < hi -> M' x = Some (Z_to_bv 8 0).
